diff --git a/apps/roam/src/components/canvas/overlays/TextLinkOverlay.tsx b/apps/roam/src/components/canvas/overlays/TextLinkOverlay.tsx
new file mode 100644
index 00000000..e90b469f
--- /dev/null
+++ b/apps/roam/src/components/canvas/overlays/TextLinkOverlay.tsx
@@ -0,0 +1,81 @@
+import React from "react";
+import {
+  HyperlinkButton,
+  T,
+  TLShape,
+  TLShapeId,
+  useEditor,
+  useValue,
+} from "tldraw";
+
+type TextLink = { id: TLShapeId; url: string; left: number; top: number };
+
+// Matches the hit area of tldraw's .tl-hyperlink-button.
+const BUTTON_SIZE = 44;
+
+// meta is unvalidated, so this is the only guard before an href. Returning the
+// parsed form keeps the href identical to what passed validation.
+export const getTextShapeLinkUrl = (shape: TLShape): string | undefined => {
+  if (shape.type !== "text") return undefined;
+  const { url } = shape.meta;
+  if (typeof url !== "string" || !T.linkUrl.isValid(url)) return undefined;
+  try {
+    // linkUrl resolves relative paths against a dummy origin; only absolute URLs render.
+    return new URL(url).href;
+  } catch {
+    return undefined;
+  }
+};
+
+// Text bounds hug the glyphs, so the icon sits just outside the right edge
+// rather than in the shape corner where geo shapes draw it.
+export const TextLinkOverlay = (): JSX.Element => {
+  const editor = useEditor();
+  const links = useValue<TextLink[]>(
+    "textShapeLinks",
+    () => {
+      const viewport = editor.getViewportPageBounds();
+      return editor.getCurrentPageShapes().flatMap((shape) => {
+        const url = getTextShapeLinkUrl(shape);
+        if (!url) return [];
+        const bounds = editor.getShapePageBounds(shape.id);
+        if (!bounds || !viewport.collides(bounds)) return [];
+        const anchor = editor.pageToViewport({
+          x: bounds.maxX,
+          y: bounds.midY,
+        });
+        return [
+          {
+            id: shape.id,
+            url,
+            left: anchor.x,
+            top: anchor.y - BUTTON_SIZE / 2,
+          },
+        ];
+      });
+    },
+    [editor],
+  );
+  const zoomLevel = useValue("zoomLevel", () => editor.getZoomLevel(), [
+    editor,
+  ]);
+
+  return (
+    <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
+      {links.map(({ id, url, left, top }) => (
+        <div
+          key={id}
+          style={{
+            position: "absolute",
+            left: `${left}px`,
+            top: `${top}px`,
+            width: `${BUTTON_SIZE}px`,
+            height: `${BUTTON_SIZE}px`,
+          }}
+        >
+          <HyperlinkButton url={url} zoomLevel={zoomLevel} />
+        </div>
+      ))}
+    </div>
+  );
+};
diff --git a/apps/roam/src/utils/__tests__/textLinkOverlay.test.ts b/apps/roam/src/utils/__tests__/textLinkOverlay.test.ts
new file mode 100644
index 00000000..3e10659a
--- /dev/null
+++ b/apps/roam/src/utils/__tests__/textLinkOverlay.test.ts
@@ -0,0 +1,101 @@
+import { describe, expect, it } from "vitest";
+import { createTLSchema, TLShape } from "tldraw";
+import { getTextShapeLinkUrl } from "~/components/canvas/overlays/TextLinkOverlay";
+
+const makeShape = ({
+  type = "text",
+  meta = {},
+}: {
+  type?: string;
+  meta?: Record<string, unknown>;
+} = {}): TLShape =>
+  ({
+    id: "shape:t1",
+    typeName: "shape",
+    type,
+    x: 0,
+    y: 0,
+    rotation: 0,
+    index: "a1",
+    parentId: "page:page",
+    isLocked: false,
+    opacity: 1,
+    meta,
+    props: {
+      color: "black",
+      size: "m",
+      font: "draw",
+      textAlign: "middle",
+      w: 100,
+      text: "hello",
+      scale: 1,
+      autoSize: true,
+    },
+  }) as unknown as TLShape;
+
+const withUrl = (url: unknown): TLShape => makeShape({ meta: { url } });
+
+describe("getTextShapeLinkUrl", () => {
+  it("returns the parsed href for a valid link", () => {
+    expect(getTextShapeLinkUrl(withUrl("https://Example.com"))).toBe(
+      "https://example.com/",
+    );
+    expect(getTextShapeLinkUrl(withUrl("mailto:a@b.co"))).toBe("mailto:a@b.co");
+  });
+
+  it("treats a missing or cleared link as no link", () => {
+    expect(getTextShapeLinkUrl(makeShape())).toBeUndefined();
+    expect(getTextShapeLinkUrl(withUrl(""))).toBeUndefined();
+    expect(getTextShapeLinkUrl(withUrl(42))).toBeUndefined();
+  });
+
+  it("ignores links on shapes other than text", () => {
+    const geo = makeShape({
+      type: "geo",
+      meta: { url: "https://example.com" },
+    });
+    expect(getTextShapeLinkUrl(geo)).toBeUndefined();
+  });
+
+  // meta has no schema, so a collaborator or API writer can store anything here.
+  it("rejects protocols that could run script", () => {
+    expect(getTextShapeLinkUrl(withUrl("javascript:alert(1)"))).toBeUndefined();
+    expect(
+      getTextShapeLinkUrl(withUrl(" javascript:alert(1)")),
+    ).toBeUndefined();
+    expect(getTextShapeLinkUrl(withUrl("data:text/html,x"))).toBeUndefined();
+  });
+
+  it("rejects relative URLs that linkUrl resolves against a dummy origin", () => {
+    expect(getTextShapeLinkUrl(withUrl("/page"))).toBeUndefined();
+    expect(getTextShapeLinkUrl(withUrl("//evil.example/x"))).toBeUndefined();
+  });
+});
+
+describe("text shape link persistence", () => {
+  // The stock schema is what older extension builds and the sync worker use.
+  const stockSchema = createTLSchema();
+
+  it("validates a text shape carrying meta.url against the stock schema", () => {
+    expect(() =>
+      stockSchema.validateRecord(
+        {} as never,
+        withUrl("https://example.com") as never,
+        "initialize",
+        null,
+      ),
+    ).not.toThrow();
+  });
+
+  it("round-trips meta.url through a snapshot load with no migration", () => {
+    const shape = withUrl("https://example.com");
+    const migrated = stockSchema.migrateStoreSnapshot({
+      store: { [shape.id]: shape },
+      schema: stockSchema.serialize(),
+    });
+    expect(migrated.type).toBe("success");
+    const loaded = (migrated as unknown as { value: Record<string, TLShape> })
+      .value[shape.id];
+    expect(loaded.meta.url).toBe("https://example.com");
+  });
+});

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

